<?php use app\services\Ui;use app\services\Workflow;use yii\helpers\Html;$this->title=$row['title'].' · KPI';$actor=Yii::$app->user->identity;$owner=(int)$actor->id===(int)$row['employee_id'];$steps=json_decode($row['route_snapshot']??'[]',true);$current=$steps[(int)$row['step']]??null;$editable=$owner && in_array($row['status'],['draft','returned'],true);$snap=json_decode($row['rule_snapshot']??'[]',true); ?>
<div class="page-heading"><div><span class="eyebrow">ARIZA #<?= (int)$row['id'] ?> · <?= Ui::h($row['activity_date']) ?></span><h1><?= Ui::h($row['title']) ?></h1><p><?= Ui::h($employee->name) ?> · <?= Ui::h($period['name']) ?></p></div><?= Ui::status($row['status']) ?></div>
<div class="form-grid"><div><section class="card"><div class="card-heading"><h2>Faoliyat ma’lumotlari</h2><?php if($editable)echo Html::a('Tahrirlash',['kpi/create','id'=>$row['id']],['class'=>'button secondary']); ?></div><p class="indicator-name"><?= Ui::h($indicator['name']) ?></p><dl class="details"><div><dt>Ko‘rsatkich kodi</dt><dd><?= Ui::h($indicator['code']) ?></dd></div><div><dt>Miqdor</dt><dd><?= (int)$row['quantity'] ?></dd></div><div><dt><?= $row['status']==='approved'?'Tasdiqlangan ball':'Dastlabki ball' ?></dt><dd class="large-score"><?= Ui::money($row['score_cents']) ?></dd></div><?php if($row['metric_value']!==null): ?><div><dt>Formula qiymati</dt><dd><?= Ui::h($row['metric_value']) ?></dd></div><?php endif ?><div><dt>Qoida versiyasi</dt><dd><?= isset($snap['revision'])?'#'.(int)$snap['revision']:'Yuborilganda saqlanadi' ?></dd></div></dl><?php if($row['notes']): ?><p class="preserve"><?= Ui::h($row['notes']) ?></p><?php endif ?><?php if($rule && !$rule['enabled'] && !$row['rule_snapshot']): ?><div class="alert warning">Qoida qaror kutmoqda: <?= Ui::h($indicator['source_note']) ?></div><?php endif ?></section>
<section class="card"><h2>Tasdiqlovchi dalillar</h2><?php if(!$files): ?><?= Ui::empty('Tahrirlash sahifasida dalil yuklang.') ?><?php else: ?><ul class="file-list"><?php foreach($files as $file): ?><li><span class="file-icon">↧</span><div><?= Html::a(Ui::h($file['name']),['kpi/download','id'=>$file['id']],['class'=>'text-link']) ?><small><?= number_format($file['size']/1024,1) ?> KB · <?= Ui::h($file['mime']) ?></small></div><?php if($editable): ?><?= Html::beginForm(['kpi/delete-evidence','id'=>$file['id']],'post') ?><button class="button small danger">Olib tashlash</button><?= Html::endForm() ?><?php endif ?></li><?php endforeach ?></ul><?php endif ?></section>
<section class="card"><h2>Harakatlar tarixi</h2><ol class="timeline"><?php foreach($history as $event): ?><li><div><b><?= Ui::h($event['actor']) ?></b><span class="muted"><?= date('d.m.Y H:i',$event['created_at']) ?></span></div><span class="pill"><?= Ui::h(['save'=>'Saqlandi','submit'=>'Yuborildi','approve'=>'Bosqich tasdig‘i','return'=>'Qaytarildi','reject'=>'Rad etildi','appeal'=>'Apellyatsiya','revoke'=>'Tasdiq bekor qilindi','withdraw'=>'Qaytarib olindi','remove_evidence'=>'Dalil olib tashlandi'][$event['action']]??$event['action']) ?></span><p><?= Ui::h($event['reason']) ?></p></li><?php endforeach ?></ol></section></div>
<aside><section class="card"><h2>Tasdiqlash yo‘li</h2><?php if(!$steps): ?><p class="muted">Yuborilganda tasdiqlash bosqichlari belgilanadi.</p><?php else: ?><ol class="steps"><?php foreach($steps as $i=>$step): ?><li class="<?= $row['status']==='approved' || $i<(int)$row['step']?'done':'' ?>"><span><?= $i+1 ?></span><div><b><?= Ui::h($step['name']) ?></b><small><?= Ui::h(implode(', ',array_map(fn($r)=>app\models\User::ROLES[$r]??$r,json_decode($step['roles'],true)))) ?></small></div></li><?php endforeach ?></ol><?php endif ?><?php if($period['closed']): ?><div class="alert warning">Bu davr yopilgan.</div><?php elseif($editable): ?><?= Html::beginForm(['kpi/act','id'=>$row['id']],'post') ?><?= Html::hiddenInput('action','submit') ?><button class="button full">Tekshiruvga yuborish →</button><?= Html::endForm() ?><?php endif ?>
<?php if(!$period['closed'] && $owner && $row['status']==='submitted'): ?><?= Html::beginForm(['kpi/act','id'=>$row['id']],'post') ?><?= Html::hiddenInput('action','withdraw') ?><button class="button secondary full">Qoralamaga qaytarish</button><?= Html::endForm() ?><?php endif ?></section>
<?php if(!$period['closed'] && !$owner && $current && in_array($row['status'],['submitted','review'],true) && in_array($actor->role,json_decode($current['roles'],true),true)): ?><section class="card"><h2>Tekshiruvchi qarori</h2><?= Html::beginForm(['kpi/act','id'=>$row['id']],'post') ?><?php if(in_array($snap['calc_type']??'',['Ballgacha','DarajaShkalasi'],true)): ?><?= Ui::input('Ekspert bahosi (maks. '.($snap['upper_score']??'').')','expert_score',$row['expert_score'],'number',['min'=>0,'max'=>$snap['upper_score'],'step'=>'.01']) ?><?php endif ?><?= Ui::area('Qaror izohi / sababi','reason','',['required'=>true,'maxlength'=>2000]) ?><div class="stack"><button class="button" name="action" value="approve"><?= (int)$row['step']===count($steps)-1?'Yakuniy tasdiqlash':'Bosqichni tasdiqlash' ?></button><button class="button secondary" name="action" value="return">To‘ldirishga qaytarish</button><button class="button danger" name="action" value="reject">Rad etish</button></div><?= Html::endForm() ?></section><?php endif ?>
<?php $last=$steps?end($steps):null;if(!$period['closed'] && !$owner && $row['status']==='approved' && $last && in_array($actor->role,json_decode($last['roles'],true),true)): ?><section class="card"><h2>Qarorni bekor qilish</h2><p class="muted">Tasdiqlangan ball qaytariladi, ariza yakuniy tekshiruvga o‘tadi.</p><?= Html::beginForm(['kpi/act','id'=>$row['id']],'post') ?><?= Ui::area('Bekor qilish sababi','reason','',['required'=>true,'maxlength'=>2000]) ?><button class="button danger" name="action" value="revoke">Tasdiqni bekor qilish</button><?= Html::endForm() ?></section><?php endif ?>
<?php if(!$period['closed'] && $owner && in_array($row['status'],['returned','rejected'],true)): ?><section class="card"><h2>Apellyatsiya</h2><?= Html::beginForm(['kpi/act','id'=>$row['id']],'post') ?><?= Ui::area('Qayta ko‘rib chiqish sababi','reason','',['required'=>true,'maxlength'=>2000]) ?><button class="button secondary" name="action" value="appeal">Apellyatsiya yuborish</button><?= Html::endForm() ?></section><?php endif ?></aside></div>
